import ast,json,hashlib,copy
from pathlib import Path
p=json.load(open('proposal.json'));r=json.load(open('runtime_view.json'))
def validate(x,s,path='study'):
 types={'object':dict,'array':list,'string':str,'boolean':bool}
 if 'type'in s:assert isinstance(x,types[s['type']]),(path,'type')
 if isinstance(x,dict):
  assert all(k in x for k in s.get('required',[])),(path,'required')
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),(path,'extra')
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):validate(v,s.get('items',{}),path+str(i))
 if isinstance(x,str):assert len(x)>=s.get('minLength',0),path
 if 'enum'in s:assert x in s['enum'],path
 if 'const'in s:assert x==s['const'],path
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
base=ast.parse(Path('history_g3_r0026_context_field_project.py').read_text())
methods=lambda t:{n.name:n for c in t.body if isinstance(c,ast.ClassDef) for n in c.body if isinstance(n,ast.FunctionDef)}
old=methods(base)
expected_hashes={t['id']:t['source_sha256'] for t in r['context']['history']}
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()==expected_hashes['baseline-din']
assert hashlib.sha256(Path('history_g3_r0026_context_field_project.py').read_bytes()).hexdigest()==expected_hashes['g3-r0026-context_field_project']
normalized=[]
allowed={'copy','math','torch','unirank'}
for v in p['variants']:
 source=Path(v['file']).read_text();tree=ast.parse(source);compile(source,v['file'],'exec')
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Name):assert n.id not in {'open','exec','eval','__import__','os','sys','subprocess','requests','socket'}
  if isinstance(n,ast.Attribute):assert n.attr not in {'backward','step','zero_grad','load','save'}
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==v['config']
 m=methods(tree);init=m['__init__']
 defaults={a.arg:ast.literal_eval(d) for a,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 normalize=lambda z:list(z) if isinstance(z,tuple) else z
 assert all(normalize(defaults[k])==normalize(val) for k,val in config.items())
 unchanged=[k for k in old if k not in {'__init__','forward','training_loss'}]
 for k in unchanged:assert ast.dump(m[k])==ast.dump(old[k]),(v['name'],k)
 old_calls=[ast.dump(n) for n in ast.walk(old['__init__']) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn']
 new_calls=[ast.dump(n) for n in ast.walk(init) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn']
 assert old_calls==new_calls
 # Only the cache statement/block differs in forward.
 forward=copy.deepcopy(m['forward'])
 forward.body=[n for n in forward.body if not (isinstance(n,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='_context_gradient_ids' for t in n.targets))]
 for n in forward.body:
  if isinstance(n,ast.If):n.body=[a for a in n.body if not (isinstance(a,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='_context_gradient_ids' for t in a.targets))]
 assert ast.dump(forward)==ast.dump(old['forward']),v['name']
 mode=config['context_gradient_rule']
 normalized.append(source.replace(\"'context_gradient_rule': '\"+mode+\"'\",\"'context_gradient_rule': 'MODE'\",1).replace(\"context_gradient_rule='\"+mode+\"'\",\"context_gradient_rule='MODE'\",1))
 print(v['name'], 'syntax/config/imports/inherited-source checks passed',hashlib.sha256(source.encode()).hexdigest())
assert len(set(normalized))==1
print('Study schema, protocol, evidence IDs, baseline/ancestor hashes and four-cell source identity: PASS')
print('Unchanged inherited helpers:',','.join(unchanged))
PY"

